-- =========================================================
-- CONFERÊNCIA
-- =========================================================


SELECT
    ano,
    COUNT(*) AS total_ies

FROM indicador_ies_inep

GROUP BY ano

ORDER BY ano DESC;


SELECT
    ano,
    COUNT(*) AS total_cursos

FROM indicador_curso_inep

GROUP BY ano

ORDER BY ano DESC;


-- =========================================================
-- IFAL
-- =========================================================

SELECT
    *

FROM vw_qualidade_ies_inep

WHERE
    sigla = 'IFAL'

ORDER BY ano DESC;


SELECT
    instituicao,
    sigla,
    curso,
    grau_academico,
    modalidade,
    ano,
    conceito_enade_faixa,
    idd_faixa,
    cpc_faixa

FROM vw_qualidade_curso_inep

WHERE
    sigla = 'IFAL'

ORDER BY
    curso,
    ano DESC;


-- =========================================================
-- AMOSTRA NACIONAL
-- =========================================================

SELECT
    instituicao,
    sigla,
    estado,
    ano,
    igc_continuo,
    igc_faixa

FROM vw_qualidade_ies_inep

WHERE
    igc_faixa IS NOT NULL

ORDER BY
    igc_continuo DESC NULLS LAST

LIMIT 20;
